insert into cisco.cisco_decks (id, slug, title, sermon_id, metadata)
insert into cisco.cisco_slides (deck_id, position, html, outline_html, bg, notes)
values
  ('c1000000-0000-4000-8000-000000000004', 1, '<img class="slide-image" src="/sermons/the-obvious/title.jpg" alt="The Obvious — the key to transformation is right under our nose. Deuteronomy 6:4–9, 20">', '<p><strong>THE OBVIOUS</strong> — <em>The key to transformation is right under our nose.</em></p><p>It''s strange how easily we can overlook the events of transformation simply because we stare at them every day.</p>', null, 'Title up. Let it breathe through the welcome.'),
  ('c1000000-0000-4000-8000-000000000004', 2, '<div class="fill parchment"></div><div class="panel wide"><div class="statement">Sometimes the most difficult things to see are not the things that are hidden.</div></div><div class="ambient-rule"></div>', '<p>Sometimes the <strong>most difficult things to see</strong> are not the things that are hidden.</p><p>&ndash; They''re the things that <strong>become all too familiar.</strong></p><p>We can spend a lot of time thinking about <strong>what we need but don''t have.</strong></p><p>&ndash; The hidden belief is that transformation is expensive, requires a lot of trouble.<br>&ndash; More money. More people. More talent. More opportunities. More resources.</p>', null, 'The screen holds the setup. YOU land ''all too familiar.'''),
  ('c1000000-0000-4000-8000-000000000004', 3, '<div class="fill parchment"></div><div class="panel wide"><p class="kicker">What if&hellip;</p><div class="question">&hellip;we''re overlooking what God has already put <strong>right in front of us?</strong></div></div><div class="ambient-rule"></div>', '<p><strong>What if</strong> one of our biggest problems <strong>isn''t what we don''t have?</strong></p><p><strong>What if</strong> we''re overlooking what God has already <strong>put right in front of us?</strong></p><p>How can something be right in front of us every day — but yet we never see what it could become?</p><p><strong>How do we miss what''s right in front of us?</strong> We buy technology and immediately learn how it can entertain us. We discover a new restaurant and think about eating there. We get a new vehicle and think about where we can go. We meet somebody new and we start looking for what we have in common.</p><p>Nothing wrong with any of that.</p>', null, 'Both ''what if'' questions live here — deliver the first one before the slide''s line.'),
  ('c1000000-0000-4000-8000-000000000004', 4, '<div class="fill parchment"></div><div class="panel wide"><p class="kicker">The question we rarely ask</p><div class="question">&ldquo;How could God use this for His purpose?&rdquo;</div></div><div class="ambient-rule"></div>', '<p><strong>But what if</strong> there is another question we rarely ask?</p><p><strong>How could God use this for His purpose?</strong></p><p><strong>Is it possible</strong> that the place to start is by just using what we already have?</p>', null, 'The anchor question of the whole sermon. It comes back at the end. Let it sit.'),
  ('c1000000-0000-4000-8000-000000000004', 5, '<div class="fill parchment"></div><div class="panel wide"><p class="kicker">Deuteronomy 6:4&ndash;9</p><div class="scripture">Hear, O Israel: The LORD our God, the LORD is one. Love the LORD your God with all your heart and with all your soul and with all your strength. <em>These commandments that I give you today are to be on your hearts.</em> Impress them on your children. Talk about them when you sit at home and when you walk along the road, when you lie down and when you get up. Tie them as symbols on your hands and bind them on your foreheads. Write them on the doorframes of your houses and on your gates.</div></div><div class="ambient-rule"></div>', '<p><strong>Moses told the Israelites, &ldquo;Look around, people.&rdquo;</strong></p><p>Background to Deut. — <strong>read Deut. 6:4&ndash;9.</strong></p><p><strong>Moses wasn''t merely giving them information. He''s teaching them to build a new perspective.</strong></p><p><strong>Don''t confine</strong> God''s Word to one religious moment. Surround yourself with reminders of it. Build it into your day. Build it into your house. Build it into your relationships. Build it into the raising of your children.</p>', null, 'The verse is on the screen (your outline''s instruction). Read it, then teach from it.'),
  ('c1000000-0000-4000-8000-000000000004', 6, '<div class="fill parchment"></div><div class="panel wide"><div class="mega">&ldquo;Look around, people.&rdquo;</div></div><div class="ambient-rule"></div>', '<p>&ldquo;These commandments that I give you today are to be on your hearts.&rdquo; — <strong>Destination:</strong> the heart. <strong>The means:</strong> doorpost, hand, forehead, conversations, morning, evening, and roadway.</p><p>Your house? <strong>Use it.</strong> Your doorway? <strong>Use it.</strong> Your hands? <strong>Use them.</strong> Your forehead? <strong>Use it.</strong> Your conversations with your children? <strong>Use them.</strong> Walking down the road? <strong>Use that.</strong> Sitting around the house? <strong>Use that.</strong> Getting up in the morning? <strong>Use that.</strong> Going to bed? <strong>Use that.</strong></p><p>Moses isn''t pointing them toward <strong>some extraordinary resource.</strong> He''s saying: <strong>Look around.</strong> There''s a door — write it there. You have children — talk to them. You''re going somewhere — talk about it while you''re walking. You''re sitting around the house — talk about it there. You''re getting ready for bed — there''s another opportunity. You''re waking up — there''s another one.</p><p><strong>Moses is calling on us to turn ordinary events into a DELIVERY SYSTEM for the Word of God.</strong></p>', null, 'This one anchor holds the entire ''use it'' litany. The screen stays put; you deliver.'),
  ('c1000000-0000-4000-8000-000000000004', 7, '<div class="fill parchment"></div><div class="panel wide"><p class="kicker">Make the Word of God part of the</p><div class="mega">Architecture</div><div class="question">of your life.</div></div><div class="ambient-rule"></div>', '<p>This wasn''t: &ldquo;Remember to have a Bible lesson occasionally.&rdquo; It was much bigger.</p><p><strong>Make the Word of God part of the architecture of your life.</strong></p><p>Israel now possessed God''s revealed instruction in a form that could be remembered, taught, repeated, written, displayed, and deliberately passed from one generation to another.</p>', null, 'The landing of the Moses movement.'),
  ('c1000000-0000-4000-8000-000000000004', 8, '<div class="fill parchment"></div><div class="panel wide"><p class="kicker">None of those events were new</p><div class="statement">What Moses changed was <strong>the purpose attached to them.</strong></div></div><div class="ambient-rule"></div>', '<p><strong>There''s a question nobody is asking: why would Moses have to tell them this?</strong></p><p><strong>Moses is commanding something that apparently wasn''t happening automatically.</strong></p><p>They had doors before Moses mentioned doorposts. They had homes. They had children. They had conversations. They walked the roads. They woke up. They went to sleep.</p><p>None of those events were new. What Moses changed was <strong>the purpose attached to them.</strong></p>', null, null),
  ('c1000000-0000-4000-8000-000000000004', 9, '<div class="fill parchment"></div><div class="panel wide"><div class="statement">Maybe we just haven''t learned how to see the <strong>Kingdom possibilities</strong> in the resources we <strong>already have.</strong></div></div><div class="ambient-rule"></div>', '<p><strong>Maybe our greatest Kingdom problem isn''t that we don''t have enough resources.</strong></p><p><strong>Maybe we just haven''t learned how to see the Kingdom possibilities in the resources we already have.</strong></p>', null, 'The thesis of the sermon, restated. Slow down.'),
  ('c1000000-0000-4000-8000-000000000004', 10, '<div class="fill parchment"></div><div class="panel wide"><p class="kicker">Obvious questions</p><div class="rows"><div><span class="q">What do I <strong>already</strong> have?</span></div><div><span class="q">Who do I <strong>already</strong> know?</span></div><div><span class="q">Where do I <strong>already</strong> go?</span></div><div><span class="q">What am I <strong>already</strong> good at?</span></div><div><span class="q">What conversations am I <strong>already</strong> having?</span></div></div></div><div class="ambient-rule"></div>', '<p><strong>Obvious questions:</strong> What do I already have? Who do I already know? Where do I already go? What am I already good at? What technology am I already using? What conversations am I already having? At what places am I already hanging out?</p><p>Moses wanted the Israelites to build habits that would keep them seeing it over and over — because whatever isn''t <strong>deliberately built</strong> into our lives eventually gets crowded out by everything that is.</p><p><strong>God didn''t give Israel new things to do. He gave them new reasons (perspectives).</strong></p>', null, 'Read a couple, let the room fill in the rest.'),
  ('c1000000-0000-4000-8000-000000000004', 11, '<div class="fill parchment"></div><div class="panel wide"><p class="kicker">The danger wasn''t scarcity</p><div class="mega">Walking into abundance and going blind.</div></div><div class="ambient-rule"></div>', '<p>The danger wasn''t scarcity. The danger wasn''t the enemy. The danger wasn''t the wilderness.</p><p><strong>The danger was walking into abundance and going blind.</strong></p><p>The solution was, <strong>create new habits.</strong></p>', null, null),
  ('c1000000-0000-4000-8000-000000000004', 12, '<div class="fill parchment"></div><div class="panel wide"><div class="question">Has the Kingdom become something we <strong>believe in</strong> without becoming something we <strong>build our lives around?</strong></div></div><div class="ambient-rule"></div>', '<p><strong>Our habits reveal what gets our best.</strong> Habits also explain <strong>why we overlook the obvious.</strong> We naturally build habits around what matters to us.</p><p>&ndash; We don''t have to remind ourselves constantly to <strong>check our phones.</strong><br>&ndash; We don''t need a <strong>discipleship class to teach</strong> us to open Facebook.<br>&ndash; Nobody needs to call me on Thursday afternoon and say: <em>&ldquo;Joe, remember, you''re supposed to eat supper tonight.&rdquo;</em></p><p>Here''s what we do: we buy technology and immediately learn how it can entertain us. We find a new restaurant and start planning our next dinner. We get a new vehicle and we plan a road trip.</p><p>Our lives naturally organize themselves around things we have decided matter. And that''s where the uncomfortable question creeps in:</p><p><strong>Has the Kingdom become something we believe in without it becoming something we build our lives around? It''s present in belief but absent in life.</strong></p>', null, 'The supper line is the laugh — let it land before the uncomfortable question.'),
  ('c1000000-0000-4000-8000-000000000004', 13, '<div class="fill parchment"></div><div class="panel wide"><div class="statement">Attach the things of God to things <strong>you''re already doing.</strong></div></div><div class="ambient-rule"></div>', '<p>Moses is saying: <strong>Build habits that keep God from becoming peripheral.</strong></p><p>There''s an idea in leadership called a <em>keystone habit</em> — one small &ldquo;key&rdquo; habit that begins influencing other areas of your life. (Floss &gt; &ldquo;I''m disciplined, feel great&rdquo; &gt; kiss the wife &gt; wake up ready to face the next day&hellip;)</p><p>And when I read Deuteronomy 6, it''s clear that <strong>Moses understood that principle</strong> a long time ago. He doesn''t tell them, &ldquo;Once a year, have a really big spiritual event and remind yourselves of God.&rdquo; He says when you get up — talk about it. When you sit around the house — talk about it. When you''re traveling — talk about it. When you go to bed — talk about it.</p><p><strong>Attach the things of God to things you''re already doing.</strong></p><p>Because sometimes one small, repeated habit can begin changing the environment of an entire life — hence, <strong>TRANSFORMATION!</strong></p>', null, null),
  ('c1000000-0000-4000-8000-000000000004', 14, '<div class="fill parchment"></div><div class="panel wide"><p class="kicker">Romans 12:2</p><div class="scripture">Don''t live the way this world lives. <em>Let your way of thinking be completely changed.</em> Then you will be able to test what God wants for you. And you will agree that what he wants is right. His plan is good and pleasing and perfect.</div></div><div class="ambient-rule"></div>', '<p>The Apostle Paul taught that <strong>true transformation comes from God by changing how you think.</strong></p><p>Romans 12:2 (NIrV) — on the screen.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000004', 15, '<div class="fill parchment"></div><div class="panel wide"><p class="kicker">Imagine if we started asking one question</p><div class="question">&ldquo;How can I use this moment for the Kingdom?&rdquo;</div></div><div class="ambient-rule"></div>', '<p>What if for the next week you developed one new &ldquo;keystone&rdquo; habit? Every time you pick up something, walk into some place, meet somebody — you see it as an opportunity and then ask:</p><p><strong>&ldquo;How can I use this moment for the Kingdom?&rdquo;</strong></p><p>The whole passage from Deut. is teaching Israel to <strong>train themselves to notice God in everyday, mundane events.</strong></p><p>Bought a car? How could I use this for the Kingdom? New computer? How could I use it for the Kingdom? Love drinking coffee somewhere every morning? How could God use that place? Good at woodworking? How could God use that? Have a home? How could this home bless someone? Know how to make videos (reels)? How could that communicate the Kingdom? Are you an awesome cook? Who could sit around your table?</p><p><strong>Maybe that''s the event that can make a difference for God''s Kingdom.</strong></p>', null, 'Your repeated question, now as the practical challenge.'),
  ('c1000000-0000-4000-8000-000000000004', 16, '<div class="fill parchment"></div><div class="panel wide"><div class="statement">Don''t miss what God can do through something <strong>you''ve stopped noticing.</strong></div></div><div class="ambient-rule"></div>', '<p><strong>Don''t miss what God can do through something you''ve stopped noticing.</strong></p><p>Some of our greatest Kingdom opportunities may be hiding in plain sight.</p><p>One last thought&hellip;</p>', null, null),
  ('c1000000-0000-4000-8000-000000000004', 17, '<div class="fill parchment"></div><div class="panel wide"><p class="kicker">Deuteronomy 6:20</p><div class="mega">Don''t miss the handoff.</div></div><div class="ambient-rule"></div>', '<p><strong>Don''t miss the handoff.</strong> Immediately after the instructions about teaching, Moses starts talking about <strong>children and future generations.</strong></p><p>And later in the chapter comes the beautiful question: &ldquo;In the future, when your son asks you, &lsquo;What is the meaning of the stipulations, decrees and laws&hellip;?&rsquo;&rdquo; (Deut. 6:20) — <em>You tell them what God did in Egypt.</em></p><p>Moses isn''t only worried about whether <strong>this generation knows.</strong> He''s thinking about what happens with <strong>the next generation:</strong></p><p><strong>Every generation inherits something from the generation before it. Every generation is teaching the generation behind it — even when it doesn''t realize it''s teaching.</strong></p><p>Question: <strong>How are we helping the next generation know, discover, and appreciate who God is?</strong></p>', null, null),
  ('c1000000-0000-4000-8000-000000000004', 18, '<div class="fill parchment"></div><div class="panel wide"><div class="statement">We may have <strong>more ways to communicate</strong> than any generation in history &mdash; and still fail to communicate <strong>the thing that matters most.</strong></div></div><div class="ambient-rule"></div>', '<p>In 2026 we have: phones, tablets, televisions, computers, websites, social media, text messaging, email, video, podcasts, coffee shops, restaurants, vehicles, homes, workplaces, friendships, hobbies, community events&hellip;</p><p>The problem certainly isn''t that we don''t have enough opportunities to influence others.</p><p><strong>We may have more ways to communicate than any generation in history — and still fail to communicate the thing that matters most.</strong></p>', null, null),
  ('c1000000-0000-4000-8000-000000000004', 19, '<div class="fill parchment"></div><div class="panel wide"><div class="statement stage" data-stage="1">The last time God told Israel to put something on a doorframe&hellip;</div><div class="mega stage" data-stage="2">It was blood.</div></div><div class="ambient-rule"></div>', '<p>Imagine where the Israelites stood&hellip;</p><p><strong>The last time God told Israel to put something on a doorframe, it was blood.</strong> (Egypt)</p><p>And it was the difference between life and death.</p>', null, 'One click. The second line lands by itself — give it room. Slow down here.'),
  ('c1000000-0000-4000-8000-000000000004', 20, '<div class="fill parchment"></div><div class="panel wide"><p class="kicker">God has always done His most important work on</p><div class="mega">Ordinary doorways.</div><div class="question">Claim your doorway for the Kingdom.</div></div><div class="ambient-rule"></div>', '<p><strong>God has always done His most important work on ordinary doorways.</strong></p><p><strong>Claim your doorway for the Kingdom.</strong></p>', null, null),
  ('c1000000-0000-4000-8000-000000000004', 21, '<div class="fill parchment"></div><div class="panel wide"><p class="kicker">Joshua 24:15</p><div class="scripture">&ldquo;<em>As for me and my house, we will serve the Lord.</em>&rdquo;</div></div><div class="ambient-rule"></div>', '<p>Near the end of his life, Joshua gathers the people of Israel at Shechem. He challenges them to give up foreign idols and choose whom they will follow.</p><p>Joshua said, <strong>&ldquo;As for me and my house, we will serve the Lord.&rdquo;</strong> (Joshua 24:15)</p><p><strong>Are you ready to reclaim your doorpost for the Kingdom?</strong> Walks, restaurants, cars, mornings, nights, etc.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000004', 22, '<div class="fill parchment"></div><div class="panel wide"><p class="kicker">The challenge</p><div class="nums"><div><span class="n">1</span><span class="t">Start taking notice of the daily events where transformation is hidden.</span></div><div><span class="n">2</span><span class="t">Build one &ldquo;keystone&rdquo; habit for the Kingdom and start seeing God appear in your life.</span></div></div></div><div class="ambient-rule"></div>', '<p><strong>Final challenge:</strong></p><p>1. Start taking notice of the daily events where transformation is hidden.</p><p>2. Build one &ldquo;keystone&rdquo; habit for the Kingdom and start seeing God appear in your life.</p>', null, 'Leave this up through the close.'),
  ('c1000000-0000-4000-8000-000000000004', 23, '<img class="slide-image" src="/sermons/the-obvious/title.jpg" alt="The Obvious — the key to transformation is right under our nose. Deuteronomy 6:4–9, 20">', '<p><strong>Title screen</strong> — invitation / closing prayer.</p>', null, 'Back to the title for the invitation.')
insert into cisco.cisco_deck_state (deck_id, current_slide, is_live, is_blank)
